export interface ConnectorConfig {
  airtableBaseId: string;
  airtableTableIdOrName: string;
  airtablePersonalAccessToken: string;
  fetch?: typeof fetch;
}

export interface ShopifyOrderPaidPayload {
  id: string;
  label: string;
  currency: string;
  totals: Array<{
    type: string;
    display_text: string;
    amount: number;
  }>;
  customer?: {
    contact?: {
      email?: string;
    };
  };
  ucp?: unknown;
  line_items?: unknown[];
  fulfillment?: unknown;
}

export interface HandleResult {
  airtableRecordId: string;
  createdTime: string;
}

function extractOrderId(id: string): number {
  const match = id.match(/\/(\d+)$/);
  if (!match) {
    throw new Error(`Invalid Shopify order ID format: ${id}`);
  }
  return parseInt(match[1], 10);
}

function extractTotalPrice(totals: Array<{ type: string; amount: number }>): number {
  const total = totals.find((t) => t.type === 'total');
  if (!total) {
    throw new Error('Total amount not found in order totals');
  }
  return total.amount / 100;
}

function extractEmail(payload: ShopifyOrderPaidPayload): string {
  const email = payload.customer?.contact?.email;
  if (!email) {
    return 'customer@example.com';
  }
  return email;
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.id) {
    throw new Error('Missing required field: id');
  }
  if (!payload.totals || !Array.isArray(payload.totals)) {
    throw new Error('Missing required field: totals');
  }

  const orderId = extractOrderId(payload.id);
  const total = extractTotalPrice(payload.totals);
  const email = extractEmail(payload);

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableIdOrName}`;
  const body = {
    records: [
      {
        fields: {
          'Order ID': orderId,
          'Customer Email': email,
          Total: total,
        },
      },
    ],
  };

  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtablePersonalAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} for ${url}`);
  }

  const result = (await response.json()) as {
    records: Array<{
      id: string;
      createdTime: string;
      fields: Record<string, unknown>;
    }>;
  };

  if (!result.records || result.records.length === 0) {
    throw new Error('Airtable returned no records');
  }

  return {
    airtableRecordId: result.records[0].id,
    createdTime: result.records[0].createdTime,
  };
}

