      expect(req.headers.get('authorization')).toBe('Bearer patTestToken');
      expect(req.json).toEqual({
        records: [
          {
            fields: {
              'Order ID': 6252199051413,
              'Customer Email': 'customer@example.com',
              Total: 79.77,
            },
          },
        ],
      });
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });

    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/6252199051413',
      label: '#1042',
      currency: 'USD',
      totals: [
        { type: 'subtotal', display_text: 'subtotal', amount: 6298 },
        { type: 'fulfillment', display_text: 'fulfillment', amount: 899 },
        { type: 'tax', display_text: 'tax', amount: 780 },
        { type: 'fee', display_text: 'fee', amount: 0 },
        { type: 'total', display_text: 'total', amount: 7977 },
      ],
      customer: {
        contact: {
          email: 'customer@example.com',
        },
      },
    };

    const result = await handle(payload, { ...validConfig, fetch });
    expect(result.airtableRecordId).toBe('recABC123def456');
    expect(result.createdTime).toBe('2026-07-01T12:34:56.000Z');
    expect(calls.length).toBe(1);
  });

  it('uses Bearer token authentication', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer patTestToken');
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });

    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/123',
      label: '#1',
      currency: 'USD',
      totals: [{ type: 'total', display_text: 'total', amount: 1000 }],
      customer: { contact: { email: 'test@example.com' } },
    };

    await handle(payload, { ...validConfig, fetch });
    expect(calls[0].headers.get('authorization')).toBe('Bearer patTestToken');
  });

  it('maps fields correctly: order_id, email, total_price', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { records: Array<{ fields: Record<string, unknown> }> };
      expect(body.records[0].fields['Order ID']).toBe(999);
      expect(body.records[0].fields['Customer Email']).toBe('mapped@example.com');
      expect(body.records[0].fields['Total']).toBe(42.5);
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });

    const payload: ShopifyOrderPaidPayload = {
      id: 'gid://shopify/Order/999',
      label: '#999',
      currency: 'USD',
      totals: [{ type: 'total', display_text: 'total', amount: 4250 }],
      customer: { contact: { email: 'mapped@example.com' } },
    };

    await handle(payload, { ...validConfig, fetch });
    expect(calls.length).toBe(1);
  });

  it('throws descriptive error when required field id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      label: '#1',
      currency: 'USD',
      totals: [{ type: 'total', display_text: 'total', amount: 1000 }],
      customer: { contact: { email: 'test@example.com' } },
    } as unknown as ShopifyOrderPaidPayload;

